-- Datos iniciales de Storm Intelligence (reales, de la investigación del 2 de nov de 2026).
-- Fuentes: HailPoint (radar, estimado), Census ZCTA (contornos simplificados), reportes NWS/SPC/NOAA compilados.
-- Se puede volver a ejecutar sin duplicar datos.

on conflict (zip) do update set name=excluded.name, geom=excluded.geom, bbox=excluded.bbox, source_key=excluded.source_key;

on conflict (zip,event_date,source_key) do update set max_hail_in=excluded.max_hail_in, frac_1=excluded.frac_1, frac_175=excluded.frac_175, frac_25=excluded.frac_25;

on conflict (source_key,external_id) do nothing;

on conflict (source_key,external_id) do nothing;

select (select count(*) from public.zip_boundaries) zips, (select count(*) from public.zip_boundaries where geom is not null) con_contorno, (select count(*) from public.zip_hail_stats) estadisticas, (select count(*) from public.storm_swaths) franjas, (select count(*) from public.storm_events) reportes;